#include <iostream>
#include <queue>
#include <unordered_map>
#include <utility>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    unordered_map<long long, long long> counts;
    for (int i = 0; i < n; i++) {
        long long v;
        cin >> v;
        counts[v]++;
    }
    // min-heap of (count, -value): the root ranks last
    priority_queue<pair<long long, long long>, vector<pair<long long, long long>>, greater<>> heap;
    for (const auto& kv : counts) {
        heap.push({kv.second, -kv.first});
        if ((int)heap.size() > k) heap.pop();
    }
    vector<pair<long long, long long>> out;
    while (!heap.empty()) {
        out.push_back(heap.top());
        heap.pop();
    }
    for (int i = (int)out.size() - 1; i >= 0; i--) cout << -out[i].second << ' ' << out[i].first << '\n';
    return 0;
}
